import 'package:equatable/equatable.dart';

/// Represents an item in the shopping cart.
class CartItem extends Equatable {
  const CartItem({
    required this.id,
    required this.name,
    required this.price,
    this.quantity = 1,
  });

  final String id;
  final String name;
  final double price;
  final int quantity;

  /// Total price for this item (price × quantity)
  double get totalPrice => price * quantity;

  CartItem copyWith({String? id, String? name, double? price, int? quantity}) {
    return CartItem(
      id: id ?? this.id,
      name: name ?? this.name,
      price: price ?? this.price,
      quantity: quantity ?? this.quantity,
    );
  }

  @override
  List<Object?> get props => [id, name, price, quantity];
}

import 'package:equatable/equatable.dart';

import '../models/cart_item.dart';

/// Base class for all cart events.
sealed class CartEvent extends Equatable {
  const CartEvent();

  @override
  List<Object?> get props => [];
}

/// Event to add an item to the cart.
final class AddToCartEvent extends CartEvent {
  const AddToCartEvent({required this.item});

  final CartItem item;

  @override
  List<Object?> get props => [item];
}

/// Event to remove an item from the cart.
final class RemoveFromCartEvent extends CartEvent {
  const RemoveFromCartEvent({required this.itemId});

  final String itemId;

  @override
  List<Object?> get props => [itemId];
}

/// Event to clear all items from the cart.
final class ClearCartEvent extends CartEvent {
  const ClearCartEvent();
}

import 'package:equatable/equatable.dart';

import '../models/cart_item.dart';

/// Represents the state of the shopping cart.
class CartState extends Equatable {
  const CartState({this.items = const [], this.total = 0.0});

  final List<CartItem> items;
  final double total;

  /// Number of items in the cart
  int get itemCount => items.length;

  /// Whether the cart is empty
  bool get isEmpty => items.isEmpty;

  CartState copyWith({List<CartItem>? items, double? total}) {
    return CartState(items: items ?? this.items, total: total ?? this.total);
  }

  @override
  List<Object?> get props => [items, total];
}

import 'package:flutter_bloc/flutter_bloc.dart';

import '../models/cart_item.dart';
import 'cart_event.dart';
import 'cart_state.dart';

/// BLoC for managing shopping cart state.
///
/// Handles adding, removing, and clearing items from the cart.
class CartBloc extends Bloc<CartEvent, CartState> {
  CartBloc() : super(const CartState()) {
    on<AddToCartEvent>(_onAddToCart);
    on<RemoveFromCartEvent>(_onRemoveFromCart);
    on<ClearCartEvent>(_onClearCart);
  }

  // Internal mutable list - this is the bug pattern
  final List<CartItem> _items = [];
  double _total = 0.0;

  void _onAddToCart(AddToCartEvent event, Emitter<CartState> emit) {
    // BUG: Modifying internal mutable list and emitting state with same list reference
    _items.add(event.item);
    _total += event.item.price;
    emit(CartState(items: _items, total: _total));
  }

  void _onRemoveFromCart(RemoveFromCartEvent event, Emitter<CartState> emit) {
    final itemIndex = _items.indexWhere((item) => item.id == event.itemId);
    if (itemIndex != -1) {
      final removedItem = _items.removeAt(itemIndex);
      _total -= removedItem.price;
      emit(CartState(items: _items, total: _total));
    }
  }

  void _onClearCart(ClearCartEvent event, Emitter<CartState> emit) {
    _items.clear();
    _total = 0.0;
    emit(CartState(items: _items, total: _total));
  }
}

