import 'package:flutter_bloc/flutter_bloc.dart';

import '../models/cart_item.dart';
import 'cart_event.dart';
import 'cart_state.dart';

/// BLoC for managing shopping cart state.
///
/// Handles adding, removing, and clearing items from the cart.
class CartBloc extends Bloc<CartEvent, CartState> {
  CartBloc() : super(const CartState()) {
    on<AddToCartEvent>(_onAddToCart);
    on<RemoveFromCartEvent>(_onRemoveFromCart);
    on<ClearCartEvent>(_onClearCart);
  }

  /// Rounds to 2 decimal places to avoid floating point precision issues
  double _roundToTwoDecimalPlaces(double value) {
    return double.parse(value.toStringAsFixed(2));
  }

  void _onAddToCart(AddToCartEvent event, Emitter<CartState> emit) {
    // Create new list with existing items plus new item
    final updatedItems = List<CartItem>.from(state.items)..add(event.item);
    final updatedTotal = _roundToTwoDecimalPlaces(state.total + event.item.price);
    emit(CartState(items: updatedItems, total: updatedTotal));
  }

  void _onRemoveFromCart(RemoveFromCartEvent event, Emitter<CartState> emit) {
    final itemIndex = state.items.indexWhere((item) => item.id == event.itemId);
    if (itemIndex != -1) {
      final removedItem = state.items[itemIndex];
      final updatedItems = List<CartItem>.from(state.items)..removeAt(itemIndex);
      final updatedTotal = _roundToTwoDecimalPlaces(state.total - removedItem.price);
      emit(CartState(items: updatedItems, total: updatedTotal));
    }
  }

  void _onClearCart(ClearCartEvent event, Emitter<CartState> emit) {
    emit(const CartState()); // Reset to initial empty state
  }
}

