    print('  Headers: $headers');
  }
}

// Example: Use late for guaranteed initialization
class FileProcessor {
  late String workingDirectory;
  late bool isInitialized;

  void initialize() {
    workingDirectory = '/tmp/processing';
    isInitialized = true;
  }

  String processFile(String filename) {
    if (!isInitialized) {
      throw StateError('FileProcessor not initialized');
    }
    return 'Processing $filename in $workingDirectory';
  }
}

// Example: Use nullable for optional values
class UserProfile {
  String? avatarUrl;  // Optional - user might not have an avatar
  String? bio;        // Optional - user might not have a bio

  String getAvatarUrl() {
    return avatarUrl ?? 'default-avatar.png';
