}

// Common Null Safety Patterns and Best Practices

void main() {
  print('=== Null Safety Patterns & Best Practices ===\n');

  demonstrateNullAwareOperators();
  demonstrateLateBestPractices();
  demonstrateCommonPatterns();
}

void demonstrateNullAwareOperators() {
  print('1. Null-Aware Operators:');
  print('------------------------');

  String? name;
  List<String>? items;

  // Null-aware access (?.)
  print('Name length: ${name?.length}'); // Returns null if name is null

  // Null coalescing (??)
  print('Display name: ${name ?? 'Anonymous'}'); // Use default if null

  // Null-aware assignment (??=)
  name ??= 'Default Name'; // Assign only if null
  print('After ??= assignment: $name');

  // Null-aware spread (...?)
  List<String> finalList = [
    'Always present',
    ...?items, // Only spread if items is not null
  ];
  print('Final list: $finalList');

  // Null assertion (!) - use sparingly!
  String? definitelyNotNull = 'Hello';
  print('Forced access: ${definitelyNotNull!.toUpperCase()}');

  print('');
}

void demonstrateLateBestPractices() {
  print('2. Late Keyword Best Practices:');
  print('-------------------------------');

  // ✅ Good: Late for dependency injection
  var controller = UserController();
  controller.initialize();
  print(controller.getUsers());

  // ✅ Good: Late final for expensive one-time computation
  var calculator = ExpensiveCalculator();
  print('First calculation: ${calculator.result}');
  print('Second calculation: ${calculator.result}'); // Uses cached result

  // ✅ Good: Late for two-phase initialization
  var database = Database();
  database.connect();
  database.setupTables();
  print(database.query('SELECT COUNT(*) FROM users'));

  print('');
}

void demonstrateCommonPatterns() {
  print('3. Common Patterns:');
  print('------------------');

  // Pattern 1: Nullable with default
  var settings = AppSettings();
  print('Theme: ${settings.getTheme()}');
  print('Font size: ${settings.getFontSize()}');

  // Pattern 2: Late initialization with validation
  var validator = FormValidator();
  validator.configure();
  print('Email valid: ${validator.isValidEmail('test@example.com')}');

  // Pattern 3: Nullable chain operations
  var user = User('John', null);
  var displayInfo = user.profile
      ?.avatar
      ?.url
      ?? 'No avatar';
  print('Avatar: $displayInfo');

  print('');
}

// Dependency injection pattern with late
class UserController {
  late UserService _userService;
  late Logger _logger;

  void initialize() {
    _userService = UserService();
    _logger = Logger();
  }

  String getUsers() {
    _logger.log('Fetching users');
    return _userService.fetchUsers();
  }
}

class UserService {
  String fetchUsers() => 'User data from service';
}

class Logger {
  void log(String message) => print('LOG: $message');
}

// Lazy initialization pattern
class ExpensiveCalculator {
  late final double result = _performCalculation();

  double _performCalculation() {
    print('  Performing expensive calculation...');
    // Simulate expensive computation
    return 42.0 * 1.618; // Golden ratio calculation
  }
}

// Two-phase initialization pattern
class Database {
  late String connectionString;
  late bool isConnected;
  late Map<String, String> tables;

  void connect() {
    connectionString = 'sqlite://memory';
    isConnected = true;
  }

  void setupTables() {
    if (!isConnected) throw StateError('Not connected');
    tables = {'users': 'CREATE TABLE users...', 'posts': 'CREATE TABLE posts...'};
  }

  String query(String sql) {
    if (!isConnected) throw StateError('Not connected');
    return 'Query result for: $sql';
  }
}

// Nullable with defaults pattern
class AppSettings {
  String? _theme;
  int? _fontSize;

  String getTheme() => _theme ?? 'light';
  int getFontSize() => _fontSize ?? 14;

  void setTheme(String theme) => _theme = theme;
  void setFontSize(int size) => _fontSize = size;
}

// Late with validation pattern
class FormValidator {
  late RegExp _emailRegex;
  late List<String> _bannedDomains;

  void configure() {
    _emailRegex = RegExp(r'^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$');
    _bannedDomains = ['spam.com', 'fake.org'];
  }

  bool isValidEmail(String email) {
    if (!_emailRegex.hasMatch(email)) return false;

    String domain = email.split('@').last;
    return !_bannedDomains.contains(domain);
  }
}

// Nullable chaining pattern
class User {
  final String name;
  final UserProfile? profile;

  User(this.name, this.profile);
}

class UserProfile {
  final Avatar? avatar;
  UserProfile(this.avatar);
}

class Avatar {
  final String url;
  Avatar(this.url);
}

