import 'package:cart_app/cart/bloc/cart_bloc.dart';
import 'package:cart_app/cart/models/cart_item.dart';
import 'package:cart_app/cart/view/cart_screen.dart';

void main() {
  group('Shopping Cart Integration Tests', () {
    testWidgets('Cart UI updates correctly when items are added', (tester) async {
      // Create the app
      await tester.pumpWidget(const MyApp());

      // Verify initial state - cart should be accessible
      expect(find.byIcon(Icons.shopping_cart), findsOneWidget);

      // Tap the cart button to navigate to cart screen
      await tester.tap(find.byIcon(Icons.shopping_cart));
      await tester.pumpAndSettle();

      // Verify cart is initially empty
      expect(find.text('Your cart is empty'), findsOneWidget);
      expect(find.text('\$0.00'), findsNothing); // Total not shown when empty

      // Go back to home
      await tester.tap(find.byType(BackButton));
      await tester.pumpAndSettle();

      // Add first item (T-Shirt)
      await tester.tap(find.text('Add to Cart').first);
      await tester.pumpAndSettle();

      // Navigate to cart again
      await tester.tap(find.byIcon(Icons.shopping_cart));
      await tester.pumpAndSettle();

      // Verify cart now shows the item and correct total
      expect(find.text('Your cart is empty'), findsNothing);
      expect(find.text('T-Shirt'), findsOneWidget);
      expect(find.text('\$19.99'), findsOneWidget); // Total should be visible

      // Go back and add another item
      await tester.tap(find.byType(BackButton));
      await tester.pumpAndSettle();

      // Add second item (Jeans)
      await tester.tap(find.text('Add to Cart').at(1));
      await tester.pumpAndSettle();

      // Navigate to cart again
      await tester.tap(find.byIcon(Icons.shopping_cart));
      await tester.pumpAndSettle();

      // Verify cart shows both items and updated total
      expect(find.text('T-Shirt'), findsOneWidget);
      expect(find.text('Jeans'), findsOneWidget);
      expect(find.text('\$69.98'), findsOneWidget); // 19.99 + 49.99 = 69.98
    });

    testWidgets('Cart total updates when item is removed', (tester) async {
      // Start with pre-populated cart
      final cartBloc = CartBloc();
      const tShirt = CartItem(id: '1', name: 'T-Shirt', price: 19.99);
      const jeans = CartItem(id: '2', name: 'Jeans', price: 49.99);

      await tester.pumpWidget(
        BlocProvider.value(
          value: cartBloc,
          child: const MaterialApp(home: CartScreen()),
        ),
      );

      // Add items to cart
      cartBloc.add(const AddToCartEvent(item: tShirt));
      cartBloc.add(const AddToCartEvent(item: jeans));
      await tester.pumpAndSettle();

      // Verify both items are shown with correct total
      expect(find.text('T-Shirt'), findsOneWidget);
      expect(find.text('Jeans'), findsOneWidget);
      expect(find.text('\$69.98'), findsOneWidget);

      // Remove T-Shirt
      await tester.tap(find.byIcon(Icons.delete_outline).first);
      await tester.pumpAndSettle();

      // Verify T-Shirt is removed and total is updated
      expect(find.text('T-Shirt'), findsNothing);
      expect(find.text('Jeans'), findsOneWidget);
      expect(find.text('\$49.99'), findsOneWidget);

      cartBloc.close();
    });
  });
}

