// Dart Sound Null Safety Examples

void main() {
  // === Basic Null Safety ===

  // Non-nullable - must be initialized
  String name = "Alice";
  // String name; // ❌ Error: must be initialized

  // Nullable - can be null
  String? nickname; // OK, defaults to null
  String? email = null; // Explicitly null

  print('Name: $name');
  print('Nickname: $nickname'); // prints: null

  // === Working with nullable types ===

  // Null check before use
  if (nickname != null) {
    print('Nickname length: ${nickname.length}'); // Smart cast to non-null
  }

  // Null-aware operators
  print('Email length: ${email?.length}'); // null if email is null
  print('Display name: ${nickname ?? name}'); // Use name if nickname is null

  // === Late keyword examples ===
  print('\n--- Late Keyword Examples ---');

  // Example 1: Late initialization
  LateInitializationExample example1 = LateInitializationExample();
  example1.setup();
  example1.printInfo();

  // Example 2: Expensive computation
  ExpensiveComputationExample example2 = ExpensiveComputationExample();
  print('First access: ${example2.expensiveValue}');
  print('Second access: ${example2.expensiveValue}'); // Uses cached value

  // Example 3: Circular dependencies
  CircularDependencyExample();
}

// === Late Keyword Use Cases ===

// Use Case 1: Late initialization (when you know it will be set before use)
class LateInitializationExample {
  late String databaseConnection; // Will be set in setup()
  late int userId; // Will be set in setup()

  void setup() {
    // Simulate initialization that happens after constructor
    databaseConnection = "postgresql://localhost:5432/mydb";
    userId = 12345;
  }

  void printInfo() {
    // Safe to use because we know setup() was called
    print('Database: $databaseConnection');
    print('User ID: $userId');
  }
}

// Use Case 2: Lazy initialization for expensive computations
class ExpensiveComputationExample {
  late String expensiveValue = _computeExpensiveValue();

  String _computeExpensiveValue() {
    print('Computing expensive value...');
    // Simulate expensive computation
    return 'Computed result: ${DateTime.now().millisecondsSinceEpoch}';
  }
}

// Use Case 3: Circular dependencies
class CircularDependencyExample {
  late Person person1;
  late Person person2;

  CircularDependencyExample() {
    person1 = Person('Alice');
    person2 = Person('Bob');

    // Create circular reference
    person1.friend = person2;
    person2.friend = person1;

    print('${person1.name} is friends with ${person1.friend!.name}');
    print('${person2.name} is friends with ${person2.friend!.name}');
  }
}

class Person {
  final String name;
  Person? friend; // Could use late here too if we guarantee it's always set

  Person(this.name);
}

// === Comparison: late vs nullable ===

class ConfigManager {
  // Use late when: You guarantee initialization before first use
  late String apiKey; // Will be loaded from config file
  late String databaseUrl; // Will be loaded from environment

  // Use nullable when: The value might legitimately be absent
  String? userPreference; // User might not have set this
  String? cacheDirectory; // Might not be available on all platforms

  void loadConfig() {
    apiKey = 'abc123'; // Must set this
    databaseUrl = 'localhost:5432'; // Must set this
    // userPreference and cacheDirectory can remain null
  }

  void demonstrateUsage() {
    // late variables - use directly (but ensure they're initialized)
    print('API Key: $apiKey');
    print('Database: $databaseUrl');

    // nullable variables - need null checks
    if (userPreference != null) {
      print('User preference: $userPreference');
    } else {
      print('No user preference set');
    }

    final cache = cacheDirectory ?? '/tmp/default_cache';
    print('Cache directory: $cache');
  }
}

// Examples of null safety errors and best practices

void main() {
  print('=== Null Safety Error Prevention ===');

  // Demonstrating safe practices
  SafePracticesExample example = SafePracticesExample();
  example.demonstrateSafePractices();

  print('\n=== Late vs Nullable Decision Guide ===');
  DecisionGuideExample guide = DecisionGuideExample();
  guide.demonstrate();
}

class SafePracticesExample {
  String? nullableValue;
  late String lateValue;
  bool isInitialized = false;

  void demonstrateSafePractices() {
    // ✅ Safe ways to work with nullable values
    print('1. Null-aware access:');
    print('   Length: ${nullableValue?.length ?? 0}');

    print('2. Null check with smart cast:');
    if (nullableValue != null) {
      // nullableValue is automatically cast to non-null String here
      print('   Value: ${nullableValue.toUpperCase()}');
    } else {
      print('   Value is null');
    }

    print('3. Null assertion (use carefully):');
    nullableValue = 'Hello';
    print('   Assured value: ${nullableValue!.length}'); // ! asserts non-null

    print('4. Safe late variable access:');
    initializeLateValue();
    print('   Late value: $lateValue');
  }

  void initializeLateValue() {
    if (!isInitialized) {
      lateValue = 'Initialized safely';
      isInitialized = true;
    }
  }
}

class DecisionGuideExample {
  void demonstrate() {
    print('When to use `late` vs nullable (`?`):');
    print('');

    // Scenario 1: Configuration that MUST be loaded
    ConfigService config = ConfigService();
    config.loadConfiguration();
    print('Config loaded: ${config.getApiUrl()}');

    // Scenario 2: Optional user settings
    UserSettings settings = UserSettings();
    settings.loadUserSettings();
    print('Theme: ${settings.getTheme()}');
    print('Language: ${settings.getLanguage()}');

    // Scenario 3: Widget with required initialization
    CustomWidget widget = CustomWidget();
    widget.initState();
    print('Widget ready: ${widget.isReady()}');
  }
}

// Use `late` when: Value will definitely be set before first use
class ConfigService {
  late String apiUrl;      // Required configuration
  late String appVersion;  // Always available
  late int maxRetries;     // Has default logic

  void loadConfiguration() {
    // These MUST be set - app can't function without them
    apiUrl = 'https://api.example.com';
    appVersion = '1.0.0';
    maxRetries = 3;
  }

  String getApiUrl() => apiUrl; // Safe to use directly
}

// Use nullable when: Value might legitimately be absent
class UserSettings {
  String? selectedTheme;    // User might not have chosen
  String? preferredLanguage; // Might use system default
  int? customTimeout;       // Might use app default

  void loadUserSettings() {
    // These might remain null - that's OK
    selectedTheme = null; // User hasn't chosen
    preferredLanguage = 'en'; // User specified
    customTimeout = null; // Use default
  }

  String getTheme() => selectedTheme ?? 'default';
  String getLanguage() => preferredLanguage ?? 'system-default';
}

// Use `late` for initialization patterns
class CustomWidget {
  late String id;
  late DateTime createdAt;
  String? title; // Optional title

  void initState() {
    // Called once during widget lifecycle
    id = 'widget_${DateTime.now().millisecondsSinceEpoch}';
    createdAt = DateTime.now();
    // title remains null unless set elsewhere
  }

  bool isReady() => true; // Can safely use id and createdAt
}

/*
DECISION GUIDE:

Use `late` when:
✅ Value will definitely be initialized before first use
✅ Initialization happens in constructor or init method
✅ You want to avoid null checks in your code
✅ The absence of the value indicates a programming error

Use nullable (`?`) when:
✅ Value might legitimately be absent/optional
✅ You need to handle the "no value" case gracefully  
✅ Value represents optional user input or configuration
✅ External APIs might not provide the value

ANTI-PATTERNS:
❌ Don't use `late` for values that might not be set
❌ Don't use nullable for values that are always required
❌ Don't use `!` (null assertion) unless you're certain
❌ Don't ignore nullable values without proper handling
*/

